mapper.delete:
DELETE FROM ai_feedback
WHERE message_id = #{messageId}
  AND source = 'CHAT'
  AND EXISTS (
      SELECT 1
      FROM ai_chat_message m
      WHERE m.id = ai_feedback.message_id
        AND m.user_id = #{userId}
        AND m.role = 'assistant'
  )

mapper.insert:
INSERT INTO ai_feedback (message_id, helpful, source, create_time)
SELECT #{feedback.messageId}, #{feedback.helpful}, 'CHAT', NOW()
FROM ai_chat_message m
WHERE m.id = #{feedback.messageId}
  AND m.user_id = #{userId}
  AND m.role = 'assistant'
